const params = {
  type: "object",
  properties: { order_number: { type: "string", description: "4-6 digit order number as the customer wrote it." } },
  required: ["order_number"],
  additionalProperties: false,
};
const description =
  "Look up the status of one order on the signed-in customer's account. Use when the customer asks where an order is. " +
  "Returns status and last update time only; it cannot change, cancel, or refund an order. " +
  "Orders on other accounts are never returned.";

// OpenAI Responses API -- result goes back as function_call_output with the same call_id
const openaiTool = { type: "function", name: "orders_get_status", description, parameters: params, strict: true };

// Claude Messages API -- result goes back as a tool_result block with tool_use_id
const claudeTool = { name: "orders_get_status", description, input_schema: params, strict: true };

// Gemini Interactions API -- result goes back as function_result with call_id
const geminiTool = { type: "function", name: "orders_get_status", description, parameters: params };

// One-time setup by an administrator -- never by the tool:
//   CREATE ROLE support_tool LOGIN NOBYPASSRLS;
//   GRANT SELECT (order_number, status, updated_at, account_id) ON orders TO support_tool;
//   ALTER ROLE support_tool SET statement_timeout = '2s';

// Any driver that sends parameters separately from the SQL text.
interface Db { query(sql: string, params: unknown[]): Promise<{ rows: Record<string, unknown>[] }>; }
interface Session { accountId: string }

const TEMPLATES = {
  orders_get_status: {
    sql: "SELECT order_number, status, updated_at FROM orders " +
         "WHERE account_id = $1 AND order_number = $2 LIMIT 1",
    // identity from the session; only order_number comes from the model
    params: (s: Session, input: { order_number: string }) => [s.accountId, input.order_number],
  },
} as const;

export async function runSqlTool(db: Db, name: string, input: { order_number: string }, s: Session) {
  const t = TEMPLATES[name as keyof typeof TEMPLATES];
  if (!t) {
    return { isError: true, text: `Unknown tool "${name}". Available: ${Object.keys(TEMPLATES).join(", ")}.` };
  }
  const { rows } = await db.query(t.sql, t.params(s, input));   // bound parameters, one statement
  return rows.length
    ? { isError: false, text: JSON.stringify(rows[0]) }
    : { isError: false, text: `No order ${input.order_number} on this account. Ask the customer to check the number.` };
}

const helpdeskTool = {
  type: "function",
  name: "helpdesk_tickets",
  description:
    "Read or comment on the signed-in user's helpdesk tickets. Use list_open to find tickets, get for one " +
    "ticket's detail, and add_comment to reply on a ticket. It cannot close, reassign, or delete tickets. " +
    "list_open returns at most 20 tickets, newest first; ticket_id and comment are null when not needed.",
  strict: true,
  parameters: {
    type: "object",
    properties: {
      action: { type: "string", enum: ["list_open", "get", "add_comment"] },
      ticket_id: { type: ["string", "null"] },
      comment: { type: ["string", "null"] },
    },
    required: ["action", "ticket_id", "comment"],
    additionalProperties: false,
  },
};

type Args = { action: "list_open" | "get" | "add_comment"; ticket_id: string | null; comment: string | null };

const ROUTES = {
  list_open: (_: Args) => ({ method: "GET", path: "/tickets?status=open&limit=20" }),
  get: (a: Args) => ({ method: "GET", path: `/tickets/${encodeURIComponent(need(a.ticket_id))}` }),
  add_comment: (a: Args) => ({
    method: "POST",
    path: `/tickets/${encodeURIComponent(need(a.ticket_id))}/comments`,
    body: JSON.stringify({ text: need(a.comment) }),
  }),
};

function need(v: string | null): string {
  if (!v) throw new Error("This action needs ticket_id (and comment for add_comment).");
  return v;
}

export async function runHelpdesk(args: Args, session: { userToken: string }, baseUrl: string) {
  const r = ROUTES[args.action](args);          // enum-checked; no model-supplied URL
  const res = await fetch(baseUrl + r.path, {
    method: r.method,
    headers: { Authorization: `Bearer ${session.userToken}`, "Content-Type": "application/json" },
    body: "body" in r ? r.body : undefined,
  });
  return { isError: !res.ok, text: res.ok ? await res.text() : `Helpdesk returned ${res.status}.` };
}

